CREATE TABLE public.social_daily (platform text NOT NULL, day date NOT NULL, source text NOT NULL, metrics jsonb NOT NULL DEFAULT '{}'::jsonb, followers_estimated boolean NOT NULL DEFAULT false, synced_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY (platform, day, source));
GRANT SELECT ON public.social_daily TO anon, authenticated;
GRANT ALL ON public.social_daily TO service_role;
ALTER TABLE public.social_daily ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read daily aggregates" ON public.social_daily FOR SELECT TO anon, authenticated USING (platform IN ('facebook','instagram','tiktok','linkedin'));
CREATE TABLE public.social_posts (platform text NOT NULL, post_id text NOT NULL, published_at timestamptz NOT NULL, title text NOT NULL DEFAULT '', format text NOT NULL DEFAULT 'Post', permalink text, thumbnail_path text, metrics jsonb NOT NULL DEFAULT '{}'::jsonb, synced_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(platform, post_id));
GRANT SELECT ON public.social_posts TO anon, authenticated;
GRANT ALL ON public.social_posts TO service_role;
ALTER TABLE public.social_posts ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read publications" ON public.social_posts FOR SELECT TO anon, authenticated USING (platform IN ('facebook','instagram','tiktok','linkedin'));
CREATE INDEX social_posts_period ON public.social_posts(platform,published_at);
CREATE TABLE public.social_sync_status (source text PRIMARY KEY, last_success_at timestamptz, last_attempt_at timestamptz, state text NOT NULL DEFAULT 'pending', message text, coverage jsonb NOT NULL DEFAULT '[]'::jsonb);
GRANT SELECT ON public.social_sync_status TO anon, authenticated;
GRANT ALL ON public.social_sync_status TO service_role;
ALTER TABLE public.social_sync_status ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Read safe sync status" ON public.social_sync_status FOR SELECT TO anon, authenticated USING (source IN ('facebook','facebook_organic','instagram','tiktok','tiktok_organic','linkedin','linkedin_organic'));
CREATE TABLE public.social_import_jobs (id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY, source text NOT NULL, date_from date NOT NULL, date_to date NOT NULL, priority integer NOT NULL DEFAULT 10, state text NOT NULL DEFAULT 'pending', attempts integer NOT NULL DEFAULT 0, error_message text, started_at timestamptz, finished_at timestamptz, UNIQUE(source,date_from,date_to));
GRANT ALL ON public.social_import_jobs TO service_role;
ALTER TABLE public.social_import_jobs ENABLE ROW LEVEL SECURITY;
CREATE INDEX social_import_jobs_pending ON public.social_import_jobs(state,priority,id);
CREATE FUNCTION public.claim_social_import_job() RETURNS SETOF public.social_import_jobs LANGUAGE sql SECURITY DEFINER SET search_path = public AS $$ UPDATE public.social_import_jobs SET state='running', started_at=now(), attempts=attempts+1 WHERE id=(SELECT id FROM public.social_import_jobs WHERE state='pending' OR (state='running' AND started_at < now()-interval '15 minutes') ORDER BY priority,id FOR UPDATE SKIP LOCKED LIMIT 1) RETURNING * $$;
REVOKE ALL ON FUNCTION public.claim_social_import_job() FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION public.claim_social_import_job() TO service_role;